#include <bits/stdc++.h>
using namespace std;const int D=13,N=1154;short X[N][26];int order_[N];struct O{int a,b,n,s;};vector<O>op;long long dp[14][17][65],seen=0,kept=0,hist[5];signed char q[26];uint16_t B[4];ofstream fo,fb;int part;bool gt(int p,int r){return(r==0&&p>0)||(r>0&&(p>=0||(p<0&&3*r*r>p*p)))||(r<0&&p>0&&p*p>3*r*r);}
void test(){seen++;int c=0;for(int k=0;k<N;k++){int i=order_[k],p=-8,r=0;for(int j=0;j<D;j++){int a=q[j],b=q[13+j];if(a||b){p+=a*X[i][j]+3*b*X[i][13+j];r+=a*X[i][13+j]+b*X[i][j];}}if(gt(p,r)){if(c==4){c=5;break;}B[c++]=i;}}if(c<=4){hist[c]++;for(int i=c;i<4;i++)B[i]=65535;fo.write((char*)q,26);fb.write((char*)B,8);kept++;if(c==0){cout<<"POTENTIAL free"<<endl;fo.flush();fb.flush();exit(0);}}if(seen%1000000==0)cout<<"seen "<<seen<<" kept "<<kept<<endl;}
void rec(int j,int n,int s){if(j==D){if(n==0&&s==0)test();return;}for(int idx=0;idx<(int)op.size();idx++){if(j==0&&idx%2!=part)continue;auto o=op[idx];if(n<o.n||s-o.s < -32||s-o.s>32||dp[D-j-1][n-o.n][s-o.s+32]==0)continue;q[j]=o.a;q[13+j]=o.b;rec(j+1,n-o.n,s-o.s);}}
int main(int argc,char**argv){part=atoi(argv[1]);string p=to_string(part);fo.open("scan_Q"+p+".bin",ios::binary);fb.open("scan_B"+p+".bin",ios::binary);ifstream f("source.bin",ios::binary);f.read((char*)X,sizeof(X));iota(order_,order_+N,0);mt19937 rng(133331);shuffle(order_,order_+N,rng);for(int a=-4;a<=4;a++)for(int b=-2;b<=2;b++)if(a*a+3*b*b<=16)op.push_back({a,b,a*a+3*b*b,a*b});dp[0][0][32]=1;for(int l=1;l<=13;l++)for(int n=0;n<=16;n++)for(int s=-32;s<=32;s++)for(auto o:op)if(n>=o.n&&s-o.s>=-32&&s-o.s<=32)dp[l][n][s+32]+=dp[l-1][n-o.n][s-o.s+32];rec(0,16,0);cout<<"done seen "<<seen<<" kept "<<kept<<" hist ";for(int i=0;i<=4;i++)cout<<i<<":"<<hist[i]<<" ";cout<<endl;}
